using System.Net;
using System.Net.Http.Json;
using System.Text.Json;
using Xunit;
public class LocalSessionRetentionTests
{
 [Fact]public async Task BrowserSessionReloadAndHeartbeatRenewal()=>await IdentityFixture.Run(async f=>{
 await LocalLoginTests.Seed(f);var login=await LocalLoginTests.Public(f,"/api/auth/login",new{username="Alice",password=LocalLoginTests.Password});Assert.Equal(HttpStatusCode.OK,login.StatusCode);var cookie=login.Headers.GetValues("Set-Cookie").Single(s=>s.StartsWith("__Host-Clary.Session="));Assert.DoesNotContain("expires=",cookie,StringComparison.OrdinalIgnoreCase);Assert.DoesNotContain("max-age=",cookie,StringComparison.OrdinalIgnoreCase);Assert.Equal(1L,await f.Scalar("SELECT count(*) FROM account_sessions"));Assert.InRange(Math.Abs((f.CookieExpiry()!.Value.UtcDateTime-(DateTime)(await f.Scalar("SELECT expires_at FROM account_sessions"))!).TotalSeconds),0,1);Assert.Equal(HttpStatusCode.OK,(await f.Client.GetAsync("/api/session")).StatusCode);Assert.Equal(HttpStatusCode.OK,(await f.Client.GetAsync("/api/session")).StatusCode);
 await f.Sql("UPDATE account_sessions SET expires_at=clock_timestamp()+interval '1 hour'");var beat=await f.Send(HttpMethod.Post,"/api/session/heartbeat",new{});Assert.Equal(HttpStatusCode.OK,beat.StatusCode);Assert.Equal(true,await f.Scalar("SELECT expires_at>clock_timestamp()+interval '7 hours 59 minutes' FROM account_sessions"));var renewed=beat.Headers.GetValues("Set-Cookie").Single(s=>s.StartsWith("__Host-Clary.Session="));Assert.DoesNotContain("expires=",renewed,StringComparison.OrdinalIgnoreCase);Assert.DoesNotContain("max-age=",renewed,StringComparison.OrdinalIgnoreCase);Assert.Equal(1L,await f.Scalar("SELECT count(*) FROM account_sessions"));Assert.InRange(Math.Abs((f.CookieExpiry()!.Value.UtcDateTime-(DateTime)(await f.Scalar("SELECT expires_at FROM account_sessions"))!).TotalSeconds),0,1);Assert.Equal(HttpStatusCode.OK,(await f.Client.GetAsync("/api/session")).StatusCode);
 Assert.Equal(HttpStatusCode.BadRequest,(await f.Client.PostAsJsonAsync("/api/session/logout",new{})).StatusCode);Assert.Equal(HttpStatusCode.OK,(await f.Send(HttpMethod.Post,"/api/session/logout",new{})).StatusCode);Assert.Equal(HttpStatusCode.Unauthorized,(await f.Client.GetAsync("/api/session")).StatusCode);
 },LocalLoginTests.Local);
 [Theory][InlineData("UPDATE account_sessions SET created_at=clock_timestamp()-interval '2 hours',expires_at=clock_timestamp()-interval '1 second'")][InlineData("UPDATE account_sessions SET revoked_at=clock_timestamp()")][InlineData("UPDATE users SET active=false")][InlineData("UPDATE memberships SET active=false")][InlineData("UPDATE companies SET active=false")]
 public async Task InvalidatedBrowserSessionCannotRenew(string invalidation)=>await IdentityFixture.Run(async f=>{
 await LocalLoginTests.Seed(f);Assert.Equal(HttpStatusCode.OK,(await LocalLoginTests.Public(f,"/api/auth/login",new{username="Alice",password=LocalLoginTests.Password})).StatusCode);await f.Sql(invalidation);if(invalidation.Contains("memberships")||invalidation.Contains("companies")){Assert.Equal(HttpStatusCode.OK,(await f.Client.GetAsync("/api/session")).StatusCode);var expiry=await f.Scalar("SELECT expires_at FROM account_sessions");Assert.Equal(HttpStatusCode.Forbidden,(await f.Send(HttpMethod.Post,"/api/session/heartbeat",new{})).StatusCode);Assert.Equal(expiry,await f.Scalar("SELECT expires_at FROM account_sessions"));}else{Assert.Equal(HttpStatusCode.Unauthorized,(await f.Client.GetAsync("/api/session")).StatusCode);Assert.Equal(HttpStatusCode.Unauthorized,(await f.Client.PostAsJsonAsync("/api/session/heartbeat",new{})).StatusCode);}Assert.Equal(1L,await f.Scalar("SELECT count(*) FROM account_sessions"));
 },LocalLoginTests.Local);
}
